import json,sys,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];RUN=Path(sys.argv[1]).resolve()
sp=ROOT/'data/processed/validation_20261028_152218/tcga_validation_summary.json';ep=ROOT/'data/processed/expression_features_20261028_153824/expression_feature_summary.json';mp=ROOT/'data/processed/identifier_mapping_20261028_155713/identifier_mapping_summary.json'
tcga=json.loads(sp.read_text());expr=json.loads(ep.read_text());mapping=json.loads(mp.read_text());audit=json.loads((RUN/'audit/phase5_dataset_audit.json').read_text())
shutil.copy2(ROOT/'data/processed/validation_20261028_152218/tcga_sample_case_manifest.csv',RUN/'audit/tcga_sample_case_manifest.csv')
audit['cohort']={'unique_expression_samples':tcga['unique_sample_count'],'unique_cases_or_patients':tcga['unique_patient_count'],'sample_type_counts':tcga['sample_type_counts'],'selected_primary_tumour_samples':expr['primary_tumour_samples'],'selected_primary_tumour_cases':expr['primary_tumour_cases'],'samples_with_multiple_files':expr['samples_with_multiple_expression_files'],'cases_with_multiple_primary_samples':expr['cases_with_multiple_primary_samples'],'validated_expression_files':tcga['valid_file_count']}
audit['expression_identifier_audit']={'raw_expression_gene_ids':expr['unique_versioned_ensembl_genes'],'NCBI_crosswalk_unique_Ensembl_mappings':mapping['expression_mapping_status_counts']['unique_entrez'],'crosswalk_ambiguous_Ensembl_rows':mapping['expression_mapping_status_counts']['ambiguous_entrez'],'crosswalk_unmapped_Ensembl_rows':mapping['expression_mapping_status_counts']['unmapped'],'strict_Ensembl_to_Entrez_rows_after_reverse_ambiguity_exclusion':60660-audit['identifier_exclusion_counts']['expression_rows_unmapped_or_ambiguous'],'expression_rows_excluded_before_STRING_join':audit['identifier_exclusion_counts']['expression_rows_unmapped_or_ambiguous'],'unique_mapped_expression_Entrez_ids_without_unambiguous_STRING_gene_alias':audit['identifier_exclusion_counts']['mapped_expression_genes_without_unambiguous_STRING_alias'],'final_expression_and_STRING_universe':audit['candidate_universe_genes'],'mapping_authority':'NCBI Gene gene_info exact Ensembl stable-ID dbXrefs; no symbol-only joins'}
(RUN/'audit/phase5_dataset_audit.json').write_text(json.dumps(audit,indent=2),encoding='utf8')
path=RUN/'audit/initial_dataset_audit.md';s=path.read_text(encoding='utf8')
s += f'''\n\n## Cohort identity and mapping counts\n\nThe validated local GDC metadata join supports **{tcga['unique_sample_count']:,} unique samples** and **{tcga['unique_patient_count']:,} unique cases/patients** across the expression files. Sample types are {tcga['sample_type_counts']['Primary Tumor']:,} primary-tumour samples, {tcga['sample_type_counts']['Solid Tissue Normal']:,} solid-tissue normals, and {tcga['sample_type_counts']['Metastatic']:,} metastases. Feature generation used {expr['primary_tumour_samples']:,} primary-tumour samples from {expr['primary_tumour_cases']:,} cases; five samples had multiple expression files, and 11 cases had multiple primary samples. All 1,228 locally present expression files were validated; three manifest entries are absent locally.\n\nThe source expression table has {expr['unique_versioned_ensembl_genes']:,} gene IDs. The exact NCBI crosswalk reports {mapping['expression_mapping_status_counts']['unique_entrez']:,} unique Ensembl-to-Entrez mappings, {mapping['expression_mapping_status_counts']['ambiguous_entrez']:,} ambiguous Ensembl rows, and {mapping['expression_mapping_status_counts']['unmapped']:,} unmapped rows. An additional 62 expression rows belonging to 31 Entrez IDs with multiple Ensembl records were excluded under a strict one-to-one policy. After that, 17,267 mapped Entrez IDs lacked an unambiguous STRING gene alias; the final expression × STRING universe is 18,998 genes. These stages are reported separately and are not counts of biological genes absent from the genome.\n'''
path.write_text(s,encoding='utf8');print(json.dumps({'cohort':audit['cohort'],'mapping':audit['expression_identifier_audit']},indent=2))
